#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Fabrik setup wizard: the steps of adopting the Kit that only the Operator can
# take. The fabrik-setup skill hands it over after it has written the Kit files,
# created the labels, vaults and service accounts, and protected the branch.
# Run it from the Product repo's checkout:
#   bash .claude/skills/fabrik-setup/wizard.sh
# Nothing it captures is written to disk: the Fabrik App's key, the Claude token
# and the Sentry token go straight into 1Password, where the Kit's jobs read
# them (ADR-0004).

run_wizard() {

TOTAL_STAGES=6

for tool in gh op; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool isn't installed; install it and sign in, then re-run."; exit 1; }
done
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner) || { warn "Run this from the Product repo's checkout, signed in with gh."; exit 1; }

# The fabrik-runs store (ADR-0009) holds every Product repo's Run records and
# the Weekly summary. Setup creates it only when the Operator opts in, so its
# stage shows only once it exists.
STORE="jrey8343/fabrik-runs"
HAS_STORE=0
gh repo view "$STORE" >/dev/null 2>&1 && HAS_STORE=1
(( HAS_STORE )) && TOTAL_STAGES=$((TOTAL_STAGES + 1))

banner "Fabrik setup for $REPO"

# ── 1. The Fabrik App on this repo ─────────────────────────────────────────
stage "Install the Fabrik App on $REPO"
say "Every label, comment and push the Loop makes comes from the Fabrik App."
say "It needs Issues, Pull requests and Contents (read and write), Checks (read), and never 'workflows'."
say "Checks (read) is how the Monitor sees main go red."
ask FABRIK_APP_SLUG "The Fabrik App's slug (the last part of github.com/apps/<slug>):"
say "If the App lacks Checks (read), add it first:"
step "At https://github.com/settings/apps/${FABRIK_APP_SLUG}/permissions, set Repository permissions → Checks to Read-only, then Save changes."
open_url "https://github.com/apps/${FABRIK_APP_SLUG}/installations/new"
step "Pick the account that owns $REPO."
step "Choose 'Only select repositories', add $REPO (keep the repos it already has), then Install or Save."
step "If GitHub shows a request for new permissions (Checks: read), review it and accept."
pause "Press Enter once $REPO is in the App's repository list."

# ── 1b. The Fabrik App on the fabrik-runs store ───────────────────────────
if (( HAS_STORE )); then
  stage "Install the Fabrik App on $STORE"
  say "Each run's push job writes its Run record to $STORE, and the Weekly summary is filed there."
  say "Both go through the Fabrik App, which needs Contents and Issues (read and write) on it."
  say "Those are the permissions the App already has; installing it on $STORE is what turns this on."
  open_url "https://github.com/apps/${FABRIK_APP_SLUG}/installations/new"
  step "Pick the account that owns $STORE."
  step "Choose 'Only select repositories', add $STORE (keep the repos it already has), then Install or Save."
  pause "Press Enter once $STORE is in the App's repository list."
fi

# ── 2. The Fabrik App's key in 1Password ──────────────────────────────────
stage "The Fabrik App's key in 1Password"
if op item get "Fabrik App" --vault "Fabrik App" --fields label=client-id >/dev/null 2>&1; then
  say "1Password already holds the 'Fabrik App' item in the 'Fabrik App' vault. Nothing to do."
  pause
else
  say "The push jobs mint their App token from the 'Fabrik App' item in the 'Fabrik App' vault."
  open_url "https://github.com/settings/apps/${FABRIK_APP_SLUG}"
  step "Under 'About', copy the Client ID."
  ask FABRIK_APP_CLIENT_ID "Paste the Client ID:"
  step "Under 'Private keys', click 'Generate a private key'. Your browser downloads a .pem file."
  ask FABRIK_APP_KEY_FILE "Path to the downloaded .pem file:"
  FABRIK_APP_KEY_FILE="${FABRIK_APP_KEY_FILE/#\~/$HOME}"
  if [[ ! -f "$FABRIK_APP_KEY_FILE" ]]; then
    warn "There's no file at $FABRIK_APP_KEY_FILE."
    SKIPPED+=("the 'Fabrik App' item in the 'Fabrik App' vault (fields client-id and private-key)")
  else
    op item create --vault "Fabrik App" --category "Secure Note" --title "Fabrik App" \
      "client-id[text]=$FABRIK_APP_CLIENT_ID" "private-key[concealed]=$(cat "$FABRIK_APP_KEY_FILE")" >/dev/null
    say "${GREEN}✓ stored${RESET} the 'Fabrik App' item in 1Password"
    if confirm "Delete the downloaded $FABRIK_APP_KEY_FILE now that 1Password holds it?"; then
      rm -f "$FABRIK_APP_KEY_FILE"
    fi
  fi
fi

# ── 3. The Claude token ───────────────────────────────────────────────────
stage "The Claude token"
say "Every agent job runs on your subscription through one long-lived token."
say "It lives in the 'Claude token' API Credential in the 'Fabrik' vault, with its expiry date,"
say "so 1Password's Watchtower warns you before it runs out."
CLAUDE_TOKEN_EXISTS=0
op item get "Claude token" --vault "Fabrik" >/dev/null 2>&1 && CLAUDE_TOKEN_EXISTS=1
if (( CLAUDE_TOKEN_EXISTS )) && ! confirm "1Password already holds a Claude token, which every Product repo shares. Replace it with a new one?"; then
  say "Keeping the current token."
  pause
else
  step "In another terminal, run: claude setup-token"
  step "Sign in with the account that has your subscription. It prints a token that lasts one year."
  ask_secret CLAUDE_TOKEN "Paste the token (hidden):"
  EXPIRES=$(date -v+1y +%Y-%m-%d 2>/dev/null || date -d "+1 year" +%Y-%m-%d)
  if (( CLAUDE_TOKEN_EXISTS )); then
    # Archived, not deleted, so the old token stays in the item's history.
    op item delete "Claude token" --vault "Fabrik" --archive
  fi
  TEMPLATE=$(umask 077 && mktemp)
  CLAUDE_TOKEN="$CLAUDE_TOKEN" EXPIRES="$EXPIRES" node -e '
    const item = { title: "Claude token", category: "API_CREDENTIAL", fields: [
      { id: "credential", type: "CONCEALED", label: "credential", value: process.env.CLAUDE_TOKEN },
      { id: "expires", type: "DATE", label: "expires", value: process.env.EXPIRES },
    ] };
    process.stdout.write(JSON.stringify(item));' > "$TEMPLATE"
  op item create --vault "Fabrik" --template "$TEMPLATE" >/dev/null
  rm -f "$TEMPLATE"
  unset CLAUDE_TOKEN
  say "${GREEN}✓ stored${RESET} the Claude token, expiring $EXPIRES"
  pause
fi

# ── 4. The Sentry token ───────────────────────────────────────────────────
stage "The Sentry token"
say "The Monitor files an issue for each production error Sentry reports, once"
say "monitor.errors in .fabrik/config.json names your Sentry org and project."
say "It reads Sentry with the 'Sentry token' API Credential in the 'Fabrik App' vault."
SENTRY_TOKEN_EXISTS=0
op item get "Sentry token" --vault "Fabrik App" >/dev/null 2>&1 && SENTRY_TOKEN_EXISTS=1
if (( SENTRY_TOKEN_EXISTS )) && ! confirm "1Password already holds a Sentry token, which every Product repo shares. Replace it with a new one?"; then
  say "Keeping the current Sentry token."
  pause
elif (( ! SENTRY_TOKEN_EXISTS )) && ! confirm "Does $REPO report production errors to Sentry?"; then
  say "Skipping the Sentry token. Re-run the wizard once $REPO reports to Sentry."
  pause
else
  open_url "https://sentry.io/settings/account/api/auth-tokens/new-token/"
  step "Create a token with the scopes Issue & Event: Read (event:read) and Project: Read (project:read)."
  note "An internal integration's token works too. An organization token (sntrys_…) doesn't: its scopes don't cover issues."
  note "On another Sentry host, use its token page, and set monitor.errors.url to that host."
  ask_secret SENTRY_TOKEN "Paste the token (hidden):"
  if [[ "$SENTRY_TOKEN" == sntrys_* ]]; then
    warn "That's an organization token, whose scopes don't cover issues."
    if (( SENTRY_TOKEN_EXISTS )); then
      say "Keeping the current Sentry token."
    else
      SKIPPED+=("the 'Sentry token' item in the 'Fabrik App' vault (a token with event:read and project:read)")
    fi
  else
    if (( SENTRY_TOKEN_EXISTS )); then
      # Archived, not deleted, so the old token stays in the item's history.
      op item delete "Sentry token" --vault "Fabrik App" --archive
    fi
    TEMPLATE=$(umask 077 && mktemp)
    SENTRY_TOKEN="$SENTRY_TOKEN" node -e '
      const item = { title: "Sentry token", category: "API_CREDENTIAL", fields: [
        { id: "credential", type: "CONCEALED", label: "credential", value: process.env.SENTRY_TOKEN },
      ] };
      process.stdout.write(JSON.stringify(item));' > "$TEMPLATE"
    op item create --vault "Fabrik App" --template "$TEMPLATE" >/dev/null
    rm -f "$TEMPLATE"
    say "${GREEN}✓ stored${RESET} the Sentry token"
  fi
  unset SENTRY_TOKEN
  pause
fi

# ── 5. GitHub mobile: push only when it's your move ───────────────────────
stage "GitHub mobile notifications"
say "The Loop buzzes you only when it's your move: a review request at the Merge gate,"
say "an assignment for ready-for-human work, and an @-mention for Design rounds,"
say "needs-info replies and failures. Set GitHub mobile to push exactly those."
step "In the GitHub mobile app: Profile → Settings (gear) → Notifications."
step "Turn push ON for Direct mentions, Assigned, and Review requested."
step "Turn push OFF for Actions (workflow runs), so the Loop's own runs stay quiet."
open_url "https://github.com/settings/notifications"
step "On the web page that opened, under 'System' → 'Actions', make sure nothing is sent to mobile."
note "The setting names may differ slightly between app versions: match them by meaning."
pause "Press Enter once push is set."

# ── 6. Watch the repo ─────────────────────────────────────────────────────
stage "Watch $REPO on All activity"
say "Watching on All activity puts every Loop event in your GitHub inbox, without a push."
if confirm "Watch $REPO on All activity now, with gh?"; then
  gh api --method PUT "repos/$REPO/subscription" -F subscribed=true -F ignored=false >/dev/null
  say "${GREEN}✓ watching${RESET} $REPO"
else
  open_url "https://github.com/$REPO"
  step "Click Watch (top right) → All Activity."
  pause
fi

finish
say "Next: open an issue on $REPO. Intake labels it needs-triage and the Loop takes it from there."
printf '\n'
}

run_wizard "$@"; exit
